/**
 * Chapter Practice question bank (Milestone M5).
 *
 * Every question is generated by a builder from a small mathematical data
 * object (equations, points). The diagram, expected answer, hints and worked
 * solution are all derived from that same data through the exact engine, so a
 * question can never disagree with its own diagram. Load-time assertions throw
 * if a derived fact (e.g. an integral intersection) is not satisfied.
 */

import { rat, formatRational, neg, mul, sub, div, eq as rEq, parseRational, abs, type Rational } from './rational';
import {
  type LinearEq,
  makeEq,
  parseEquation,
  isLine,
  isLinearEquationInTwoVariablesText,
  isExactSolution,
  evaluate,
  slope,
  xIntercept,
  yIntercept,
  solveForY,
  solveForX,
  lineKind,
  formatStandard,
  formatSlopeIntercept,
  sameLine,
} from './linearEquation';
import { analyzeSystem } from './system';
import type {
  TVPracticeQuestion,
  PracticeDifficulty,
  PracticeTopic,
  QuestionDiagram,
  UserAnswer,
} from './types';

const eqOf = (text: string): LinearEq => {
  const r = parseEquation(text);
  if (!r.ok || !r.equation || !isLine(r.equation)) throw new Error(`Practice bank: bad equation "${text}"`);
  return r.equation;
};

const num = (r: Rational): string => formatRational(r);
const assert = (cond: boolean, msg: string) => {
  if (!cond) throw new Error(`Practice bank integrity: ${msg}`);
};

/** Deterministic placement of the correct option so it is not always first. */
function arrangeOptions(id: string, correct: string, distractors: string[]): { options: string[]; index: number } {
  assert(!distractors.includes(correct), `${id}: distractor equals the correct option`);
  assert(new Set(distractors).size === distractors.length, `${id}: duplicate distractors`);
  const total = distractors.length + 1;
  let h = 0;
  for (const ch of id) h = (h * 31 + ch.charCodeAt(0)) >>> 0;
  const index = h % total;
  const options = [...distractors];
  options.splice(index, 0, correct);
  return { options, index };
}

interface Base {
  id: string;
  title: string;
  difficulty: PracticeDifficulty;
  topicId: PracticeTopic;
}

function choiceQuestion(
  b: Base,
  statement: string,
  correct: string,
  distractors: string[],
  hints: string[],
  workedSolution: string[],
  explanation: string,
  diagram?: QuestionDiagram
): TVPracticeQuestion {
  const { options, index } = arrangeOptions(b.id, correct, distractors);
  return { ...b, questionType: 'multiple_choice', statement, options, answer: { kind: 'choice', index }, hints, workedSolution, explanation, diagram };
}

function numericQuestion(
  b: Base,
  statement: string,
  value: Rational,
  hints: string[],
  workedSolution: string[],
  explanation: string,
  diagram?: QuestionDiagram
): TVPracticeQuestion {
  return { ...b, questionType: 'numeric', statement, answer: { kind: 'number', value }, hints, workedSolution, explanation, diagram };
}

function pairQuestion(
  b: Base,
  statement: string,
  x: Rational,
  y: Rational,
  hints: string[],
  workedSolution: string[],
  explanation: string,
  diagram?: QuestionDiagram
): TVPracticeQuestion {
  return { ...b, questionType: 'ordered_pair', statement, answer: { kind: 'pair', x, y }, hints, workedSolution, explanation, diagram };
}

// ---------------------------------------------------------------------------
// Builders
// ---------------------------------------------------------------------------

/** Pick the one linear equation among several texts. */
function identifyLinear(b: Base, texts: string[]): TVPracticeQuestion {
  const linear = texts.filter(isLinearEquationInTwoVariablesText);
  assert(linear.length === 1, `${b.id}: exactly one option must be linear in two variables`);
  return choiceQuestion(
    b,
    'Which one of the following is a linear equation in two variables?',
    linear[0],
    texts.filter((t) => t !== linear[0]),
    ['A linear equation in x and y can be written as ax + by + c = 0 with a and b not both zero.', 'Look for x or y being multiplied together, squared, or placed in a denominator.'],
    [
      `${linear[0]} can be rearranged to the form ax + by + c = 0.`,
      'The other options contain a product of the variables, a power higher than 1, or a variable in a denominator, so they are not linear.',
    ],
    'In a linear equation every variable appears only to the first power, and x and y are never multiplied together.'
  );
}

function standardFormCoefficient(b: Base, text: string, which: 'a' | 'b' | 'c'): TVPracticeQuestion {
  const e = eqOf(text);
  const v = e[which];
  return numericQuestion(
    b,
    `Move every term of "${text}" to the left side so that it reads ax + by + c = 0 (do not multiply or divide the equation). What is ${which}?`,
    v,
    ['Bring all terms to the left side: add or subtract the same thing on both sides.', 'a goes with x, b goes with y, and c is the number left over.'],
    [
      `Moving every term to the left gives ${num(e.a)}x + (${num(e.b)})y + (${num(e.c)}) = 0.`,
      `So a = ${num(e.a)}, b = ${num(e.b)}, c = ${num(e.c)}.`,
      `Therefore ${which} = ${num(v)}.`,
    ],
    'Standard form has everything on the left and 0 on the right, so the constant on the right changes sign when it moves.'
  );
}

function checkPair(b: Base, text: string, x: number, y: number): TVPracticeQuestion {
  const e = eqOf(text);
  const holds = isExactSolution(e, rat(x), rat(y));
  const lhs = sub(evaluate(e, rat(x), rat(y)), e.c);
  return choiceQuestion(
    b,
    `Is (${x}, ${y}) a solution of ${text}?`,
    holds ? 'Yes, it is a solution' : 'No, it is not a solution',
    [holds ? 'No, it is not a solution' : 'Yes, it is a solution'],
    ['Substitute the first number for x and the second for y.', 'It is a solution only if both sides become equal.'],
    [
      `Substitute x = ${x}, y = ${y} into the left side: ${num(e.a)}(${x}) + ${num(e.b)}(${y}) = ${num(lhs)}.`,
      holds
        ? `The right side is ${num(neg(e.c))}, which is equal, so the pair satisfies the equation.`
        : `The right side is ${num(neg(e.c))}, which is different, so the pair does not satisfy the equation.`,
    ],
    'An ordered pair is a solution exactly when substituting it makes the equation true.'
  );
}

function tableValue(b: Base, text: string, given: 'x' | 'y', value: number): TVPracticeQuestion {
  const e = eqOf(text);
  const r = given === 'x' ? solveForY(e, rat(value)) : solveForX(e, rat(value));
  assert(r.kind === 'unique', `${b.id}: table question needs a unique result`);
  const ans = (r as { kind: 'unique'; value: Rational }).value;
  const other = given === 'x' ? 'y' : 'x';
  return numericQuestion(
    b,
    `For the equation ${text}, a solution table has ${given} = ${value}. What is ${other}?`,
    ans,
    [`Put ${given} = ${value} into the equation.`, `Then solve the remaining equation for ${other}.`],
    [
      `Substitute ${given} = ${value} into ${text}.`,
      `Solve the resulting one-variable equation for ${other}.`,
      `${other} = ${num(ans)}, so the ordered pair is ${given === 'x' ? `(${value}, ${num(ans)})` : `(${num(ans)}, ${value})`}.`,
    ],
    'Choosing one variable and solving for the other gives one solution; changing the choice gives more.'
  );
}

function interceptQuestion(b: Base, text: string, axis: 'x' | 'y'): TVPracticeQuestion {
  const e = eqOf(text);
  const ic = axis === 'x' ? xIntercept(e) : yIntercept(e);
  assert(ic.kind === 'point', `${b.id}: intercept must be a single point`);
  const v = (ic as { kind: 'point'; value: Rational }).value;
  return numericQuestion(
    b,
    `The line ${text} meets the ${axis}-axis at the point where ${axis === 'x' ? 'y = 0' : 'x = 0'}. What is the ${axis}-intercept (the ${axis}-coordinate of that point)?`,
    v,
    [axis === 'x' ? 'On the x-axis, y is 0.' : 'On the y-axis, x is 0.', `Substitute and solve for ${axis}.`],
    [
      `Put ${axis === 'x' ? 'y' : 'x'} = 0 in ${text}.`,
      `Solve for ${axis}: ${axis} = ${num(v)}.`,
      `The line crosses the ${axis}-axis at ${axis === 'x' ? `(${num(v)}, 0)` : `(0, ${num(v)})`}.`,
    ],
    'Intercepts come from setting the other variable to zero.'
  );
}

function slopeQuestion(b: Base, text: string): TVPracticeQuestion {
  const e = eqOf(text);
  const m = slope(e);
  assert(m !== null, `${b.id}: slope must be defined`);
  return numericQuestion(
    b,
    `What is the slope of the line ${text}? (Give a whole number, decimal or fraction such as -2/3.)`,
    m as Rational,
    ['Write the equation as y = mx + k; m is the slope.', 'In ax + by + c = 0 the slope is −a/b.'],
    [`Solve for y: ${formatSlopeIntercept(e)}.`, `The coefficient of x is the slope: m = ${num(m as Rational)}.`],
    'Slope measures how much y changes when x increases by 1.'
  );
}

function lineKindQuestion(b: Base, texts: string[], wanted: 'horizontal' | 'vertical'): TVPracticeQuestion {
  const matches = texts.filter((t) => lineKind(eqOf(t)) === wanted);
  assert(matches.length === 1, `${b.id}: exactly one ${wanted} option`);
  return choiceQuestion(
    b,
    `Which of these lines is ${wanted}?`,
    matches[0],
    texts.filter((t) => t !== matches[0]),
    wanted === 'horizontal' ? ['A horizontal line keeps the same y-value everywhere.'] : ['A vertical line keeps the same x-value everywhere.'],
    [`${matches[0]} fixes ${wanted === 'horizontal' ? 'y' : 'x'} and leaves the other variable free, so it is ${wanted}.`],
    wanted === 'horizontal' ? 'Equations of the form y = k are horizontal.' : 'Equations of the form x = h are vertical.'
  );
}

function intersectionFromGraph(b: Base, t1: string, t2: string, extent: number): TVPracticeQuestion {
  const e1 = eqOf(t1);
  const e2 = eqOf(t2);
  const sys = analyzeSystem(e1, e2);
  assert(sys.type === 'unique' && sys.solution !== undefined, `${b.id}: system must be unique`);
  const s = sys.solution!;
  assert(s.x.d === 1 && s.y.d === 1 && Math.abs(s.x.n) < extent && Math.abs(s.y.n) < extent, `${b.id}: intersection must be a visible lattice point`);
  return pairQuestion(
    b,
    'The graph shows two lines. Read the point where they cross and enter it as (x, y).',
    s.x,
    s.y,
    ['The solution of the pair is the point that lies on both lines.', 'Read the x-coordinate along the horizontal axis, then the y-coordinate.'],
    [`The lines are ${formatStandard(e1)} and ${formatStandard(e2)}.`, `They cross at (${num(s.x)}, ${num(s.y)}).`, `Check: ${formatStandard(e1)} and ${formatStandard(e2)} both hold at this point.`],
    'The coordinates of the intersection satisfy both equations at the same time.',
    {
      lines: [
        { eq: e1, label: 'Line 1', colorIndex: 0 },
        { eq: e2, label: 'Line 2', colorIndex: 1 },
      ],
      extent,
      showLines: true,
    }
  );
}

function classifyPair(b: Base, t1: string, t2: string, expected: 'unique' | 'parallel' | 'coincident'): TVPracticeQuestion {
  const e1 = eqOf(t1);
  const e2 = eqOf(t2);
  const sys = analyzeSystem(e1, e2);
  assert(sys.type === expected, `${b.id}: expected ${expected}, engine says ${sys.type}`);
  const labels = { unique: 'Exactly one solution', parallel: 'No solution', coincident: 'Infinitely many solutions' } as const;
  const all = Object.values(labels);
  return choiceQuestion(
    b,
    `How many solutions does the pair ${t1} and ${t2} have?`,
    labels[expected],
    all.filter((l) => l !== labels[expected]),
    ['Compare a₁/a₂, b₁/b₂ and c₁/c₂.', 'Different a₁/a₂ and b₁/b₂ means the lines cross once.'],
    [sys.reason, `Therefore: ${labels[expected].toLowerCase()}.`],
    'The ratios of coefficients tell you whether the lines intersect, are parallel, or coincide.'
  );
}

function substitutionQuestion(b: Base, t1: string, t2: string, ask: 'x' | 'y'): TVPracticeQuestion {
  const e1 = eqOf(t1);
  const e2 = eqOf(t2);
  const sys = analyzeSystem(e1, e2);
  assert(sys.type === 'unique', `${b.id}: unique needed`);
  const s = sys.solution!;
  return numericQuestion(
    b,
    `Solve by substitution: ${t1} and ${t2}. What is the value of ${ask}?`,
    s[ask],
    ['Make one variable the subject of one equation.', 'Substitute that expression into the other equation and solve.'],
    [`Use one equation to write one variable in terms of the other.`, `Substitute into the second equation and solve the one-variable equation.`, `Back-substitute: x = ${num(s.x)}, y = ${num(s.y)}.`],
    'Substitution reduces two unknowns to one.'
  );
}

function eliminationQuestion(b: Base, t1: string, t2: string): TVPracticeQuestion {
  const e1 = eqOf(t1);
  const e2 = eqOf(t2);
  const sys = analyzeSystem(e1, e2);
  assert(sys.type === 'unique', `${b.id}: unique needed`);
  const s = sys.solution!;
  return pairQuestion(
    b,
    `Solve by elimination: ${t1} and ${t2}. Enter the solution (x, y).`,
    s.x,
    s.y,
    ['Multiply an equation so that one variable has equal (or opposite) coefficients.', 'Then subtract (or add) the equations to eliminate that variable.'],
    [`Choose a variable to eliminate and make its coefficients match.`, `Subtract or add the equations and solve the single equation that remains.`, `Back-substitute to get (x, y) = (${num(s.x)}, ${num(s.y)}).`, 'Verify in both original equations.'],
    'Adding or subtracting equal quantities keeps an equation balanced, so the solution is preserved.'
  );
}

function graphPointQuestion(b: Base, texts: string[], extent: number): TVPracticeQuestion {
  const eqs = texts.map(eqOf);
  const grid: { x: number; y: number }[] = [];
  for (let x = -extent + 1; x < extent; x++) {
    for (let y = -extent + 1; y < extent; y++) {
      if (eqs.every((e) => isExactSolution(e, rat(x), rat(y)))) grid.push({ x, y });
    }
  }
  assert(grid.length > 0, `${b.id}: at least one lattice solution must be on the grid`);
  const example = grid[0];
  return {
    ...b,
    questionType: 'graph_point',
    statement:
      texts.length === 1
        ? `Click a point on the grid that is a solution of ${texts[0]}. The line is hidden until you answer.`
        : `Click the point that is a solution of both ${texts[0]} and ${texts[1]}. The lines are hidden until you answer.`,
    answer: { kind: 'graph_point', equations: eqs },
    hints: ['Choose a value of x, then calculate y from the equation.', 'Check that your point satisfies the equation before clicking.'],
    workedSolution: [
      `For example, (${example.x}, ${example.y}) satisfies ${texts.join(' and ')}.`,
      texts.length === 1 ? 'There are infinitely many correct points; any point on the line works.' : 'Only the intersection point lies on both lines.',
    ],
    explanation: 'Every solution of a linear equation is a point of its line, and every point of the line is a solution.',
    diagram: {
      lines: eqs.map((eq, i) => ({ eq, label: `Line ${i + 1}`, colorIndex: (i === 0 ? 0 : 1) as 0 | 1 })),
      extent,
      showLines: false,
    },
  };
}

/** Which equation matches the plotted line? */
function graphReadingQuestion(b: Base, lineText: string, wrong: string[], extent: number): TVPracticeQuestion {
  const e = eqOf(lineText);
  for (const w of wrong) assert(!sameLine(e, eqOf(w)), `${b.id}: distractor "${w}" describes the same line`);
  return choiceQuestion(
    b,
    'Which equation represents the line shown in the graph?',
    lineText,
    wrong,
    ['Read the point where the line crosses each axis.', 'Test a point on the line in each option.'],
    [`The line passes through ${describeIntercepts(e)}.`, `${lineText} is satisfied by those points, so it is the equation of the line.`, 'Each other option fails for at least one of those points.'],
    'An equation represents a line exactly when the line’s points are its solutions.',
    { lines: [{ eq: e, label: 'Line', colorIndex: 0 }], extent, showLines: true }
  );
}

function describeIntercepts(e: LinearEq): string {
  const xi = xIntercept(e);
  const yi = yIntercept(e);
  const parts: string[] = [];
  if (xi.kind === 'point') parts.push(`(${num(xi.value)}, 0)`);
  if (yi.kind === 'point') parts.push(`(0, ${num(yi.value)})`);
  return parts.join(' and ');
}

// ---------------------------------------------------------------------------
// Word problems: both equations and the story are generated from one model.
// ---------------------------------------------------------------------------

function wordPairQuestion(b: Base, story: string, askLabel: string, t1: string, t2: string, ask: 'x' | 'y' | 'pair', unit = ''): TVPracticeQuestion {
  const e1 = eqOf(t1);
  const e2 = eqOf(t2);
  const sys = analyzeSystem(e1, e2);
  assert(sys.type === 'unique', `${b.id}: unique needed`);
  const s = sys.solution!;
  assert(s.x.n > 0 && s.y.n > 0, `${b.id}: word problems need positive quantities`);
  const steps = [
    `Let x and y be the unknown quantities. The story gives ${t1} and ${t2}.`,
    `Solve the pair: x = ${num(s.x)}, y = ${num(s.y)}.`,
    `Check in the story: ${formatStandard(e1)} and ${formatStandard(e2)} both hold.`,
  ];
  const hints = ['Name the two unknown quantities x and y.', 'Write one equation for each fact in the story, then solve the pair.'];
  if (ask === 'pair') return pairQuestion(b, `${story} ${askLabel}`, s.x, s.y, hints, steps, 'Two facts about two unknowns give two linear equations.');
  return numericQuestion(b, `${story} ${askLabel}${unit}`, s[ask], hints, steps, 'Two facts about two unknowns give two linear equations.');
}

function slopeFromPoints(b: Base, p1: [number, number], p2: [number, number], atX: number): TVPracticeQuestion {
  const dx = p2[0] - p1[0];
  const dy = p2[1] - p1[1];
  assert(dx !== 0, `${b.id}: points must not share x`);
  const m = rat(dy, dx);
  const k = sub(rat(p1[1]), mul(m, rat(p1[0])));
  const e = makeEq(neg(m), 1, neg(k));
  assert(isExactSolution(e, rat(p1[0]), rat(p1[1])) && isExactSolution(e, rat(p2[0]), rat(p2[1])), `${b.id}: line must pass through both points`);
  const y = solveForY(e, rat(atX));
  assert(y.kind === 'unique', `${b.id}: y unique`);
  return numericQuestion(
    b,
    `A line passes through (${p1[0]}, ${p1[1]}) and (${p2[0]}, ${p2[1]}). If the point (${atX}, y) is also on this line, what is y?`,
    (y as { kind: 'unique'; value: Rational }).value,
    ['First find the slope: (change in y) ÷ (change in x).', 'Write the equation y = mx + k and use one of the points to find k.'],
    [`Slope m = (${p2[1]} − ${p1[1]}) ÷ (${p2[0]} − ${p1[0]}) = ${num(m)}.`, `Using (${p1[0]}, ${p1[1]}): k = ${num(k)}, so the line is ${formatSlopeIntercept(e)}.`, `At x = ${atX}: y = ${num((y as { kind: 'unique'; value: Rational }).value)}.`],
    'Two points determine a line, and the slope is constant along it.'
  );
}

function findParameter(b: Base, template: 'point' | 'parallel' | 'coincident'): TVPracticeQuestion {
  if (template === 'point') {
    // 3x + k·y = 10 passes through (2, 1)  →  k = 4
    const k = rat(4);
    const e = makeEq(3, k, -10);
    assert(isExactSolution(e, rat(2), rat(1)), `${b.id}: (2,1) must satisfy`);
    return numericQuestion(
      b,
      'The equation 3x + ky = 10 has (2, 1) as a solution. Find k.',
      k,
      ['Substitute x = 2 and y = 1.', 'Solve the resulting equation for k.'],
      ['3(2) + k(1) = 10.', '6 + k = 10, so k = 4.', `Check: ${formatStandard(e)} holds at (2, 1).`],
      'A known solution turns the equation into one equation in the unknown coefficient.'
    );
  }
  // x + 2y = 3 with 2x + k y = 7 (parallel) or 6 (coincident): k = 4 either way.
  const k = rat(4);
  const c2 = template === 'parallel' ? 7 : 6;
  const e1 = makeEq(1, 2, -3);
  const e2 = makeEq(2, k, -c2);
  assert(analyzeSystem(e1, e2).type === template, `${b.id}: parameter must give a ${template} system`);
  return numericQuestion(
    b,
    `For what value of k does the pair x + 2y = 3 and 2x + ky = ${c2} have ${template === 'parallel' ? 'no solution' : 'infinitely many solutions'}?`,
    k,
    ['For both cases the ratio of the x- and y-coefficients must match: 1/2 = 2/k.', template === 'parallel' ? 'Then check that the constants do not follow the same ratio.' : 'Then check that the constants follow the same ratio.'],
    ['Same direction needs 1/2 = 2/k, so k = 4.', template === 'parallel' ? `Constants: 3/${c2} ≠ 1/2, so the lines are distinct and parallel.` : `Constants: 3/${c2} = 1/2, so the lines coincide.`, 'Therefore k = 4.'],
    'Parallel and coincident lines both have proportional x- and y-coefficients; the constants decide which one it is.'
  );
}

function triangleArea(b: Base, text: string): TVPracticeQuestion {
  const e = eqOf(text);
  const xi = xIntercept(e);
  const yi = yIntercept(e);
  assert(xi.kind === 'point' && yi.kind === 'point', `${b.id}: both intercepts`);
  const area = div(mul(abs((xi as { value: Rational }).value), abs((yi as { value: Rational }).value)), rat(2));
  return numericQuestion(
    b,
    `The line ${text} and the two coordinate axes enclose a triangle. What is its area in square units?`,
    area,
    ['Find the x-intercept and the y-intercept.', 'The axes meet at a right angle, so the area is ½ × base × height.'],
    [`x-intercept = ${num((xi as { value: Rational }).value)}, y-intercept = ${num((yi as { value: Rational }).value)}.`, `Area = ½ × ${num(abs((xi as { value: Rational }).value))} × ${num(abs((yi as { value: Rational }).value))} = ${num(area)}.`],
    'Intercepts give the legs of the right-angled triangle.'
  );
}

function fareQuestion(b: Base, fixed: number, perKm: number, total: number): TVPracticeQuestion {
  // fare = fixed + perKm·d  ⇒  perKm·d − fare + fixed = 0 in variables (d → x, fare → y).
  const e = makeEq(perKm, -1, fixed);
  const d = div(rat(total - fixed), rat(perKm));
  assert(d.d === 1, `${b.id}: whole kilometres`);
  assert(isExactSolution(e, d, rat(total)), `${b.id}: model must hold at the answer`);
  return numericQuestion(
    b,
    `A taxi charges a fixed ₹${fixed} plus ₹${perKm} for each kilometre. If x is the distance in km and y the fare in ₹, then y = ${perKm}x + ${fixed}. For a fare of ₹${total}, how many km were travelled?`,
    d,
    ['Put y = fare in the equation.', 'Solve the resulting equation for x.'],
    [`${total} = ${perKm}x + ${fixed}.`, `${perKm}x = ${total - fixed}, so x = ${num(d)}.`, `The ordered pair (${num(d)}, ${total}) lies on the line y = ${perKm}x + ${fixed}.`],
    'A real-world linear relationship is a line; each solution is one possible journey.'
  );
}

