export const getPracticeQuestionById = (id: string): TVPracticeQuestion | undefined =>
  TWO_VARIABLES_PRACTICE_BANK.find((q) => q.id === id);

export interface AnswerCheck {
  correct: boolean;
  /** True when the input could not be interpreted at all (not counted as an attempt). */
  invalid?: boolean;
}

/** Exact answer checking — no tolerance is applied to rational answers. */
export function checkPracticeAnswer(q: TVPracticeQuestion, input: UserAnswer): AnswerCheck {
  const spec = q.answer;
  switch (spec.kind) {
    case 'choice':
      return input.kind === 'choice' ? { correct: input.index === spec.index } : { correct: false, invalid: true };
    case 'number': {
      if (input.kind !== 'number') return { correct: false, invalid: true };
      const v = parseRational(input.text);
      return v ? { correct: rEq(v, spec.value) } : { correct: false, invalid: true };
    }
    case 'pair': {
      if (input.kind !== 'pair') return { correct: false, invalid: true };
      const x = parseRational(input.xText);
      const y = parseRational(input.yText);
      return x && y ? { correct: rEq(x, spec.x) && rEq(y, spec.y) } : { correct: false, invalid: true };
    }
    case 'graph_point': {
      if (input.kind !== 'graph_point') return { correct: false, invalid: true };
      const x = parseRational(String(Math.round(input.x * 1000) / 1000));
      const y = parseRational(String(Math.round(input.y * 1000) / 1000));
      if (!x || !y) return { correct: false, invalid: true };
      return { correct: spec.equations.every((e) => isExactSolution(e, x, y)) };
    }
  }
}

